:17},{"key":"7.4","parent_key":"7","label":"Other Therapeutic Use of the Medicinal Product","mandatory":true,"path_order":18},{"key":"7.5","parent_key":"7","label":"New Safety Data Related to Fixed Combination Therapies","mandatory":false,"path_order":19},{"key":"8","parent_key":null,"label":"Findings from Non-Interventional Studies","mandatory":true,"path_order":20},{"key":"9","parent_key":null,"label":"Information from Other Clinical Trials and Sources","mandatory":true,"path_order":21},{"key":"10","parent_key":null,"label":"Non-Clinical Data","mandatory":true,"path_order":22},{"key":"11","parent_key":null,"label":"Literature","mandatory":true,"path_order":23},{"key":"12","parent_key":null,"label":"Other Periodic Reports","mandatory":true,"path_order":24},{"key":"13","parent_key":null,"label":"Lack of Efficacy in Controlled Clinical Trials","mandatory":true,"path_order":25},{"key":"14","parent_key":null,"label":"Late-Breaking Information","mandatory":true,"path_order":26},{"key":"15","parent_key":null,"label":"Overview of Signals: New, Ongoing, or Closed","mandatory":true,"path_order":27},{"key":"16","parent_key":null,"label":"Signal and Risk Evaluation","mandatory":true,"path_order":28},{"key":"16.1","parent_key":"16","label":"Summary of Safety Concerns","mandatory":true,"path_order":29},{"key":"16.2","parent_key":"16","label":"Signal Evaluation","mandatory":true,"path_order":30},{"key":"16.3","parent_key":"16","label":"Evaluation of Risks and New Information","mandatory":true,"path_order":31},{"key":"16.4","parent_key":"16","label":"Characterisation of Risks","mandatory":true,"path_order":32},{"key":"16.5","parent_key":"16","label":"Effectiveness of Risk Minimisation (if applicable)","mandatory":false,"path_order":33},{"key":"17","parent_key":null,"label":"Benefit Evaluation","mandatory":true,"path_order":34},{"key":"17.1","parent_key":"17","label":"Important Baseline Efficacy and Effectiveness Information","mandatory":true,"path_order":35},{"key":"17.2","parent_key":"17","label":"Newly Identified Information on Efficacy and Effectiveness","mandatory":true,"path_order":36},{"key":"17.3","parent_key":"17","label":"Characterisation of Benefits","mandatory":true,"path_order":37},{"key":"18","parent_key":null,"label":"Integrated Benefit-Risk Analysis for Approved Indications","mandatory":true,"path_order":38},{"key":"18.1","parent_key":"18","label":"Benefit-Risk Context: Medical Need and Important Alternatives","mandatory":true,"path_order":39},{"key":"18.2","parent_key":"18","label":"Benefit-Risk Analysis Evaluation","mandatory":true,"path_order":40},{"key":"19","parent_key":null,"label":"Conclusions and Actions","mandatory":true,"path_order":41},{"key":"20","parent_key":null,"label":"Appendices to the PBRER","mandatory":true,"path_order":42}]$pack$::jsonb
    END;
    SELECT jsonb_array_length(required_sections), required_sections = tree, superseded_by
      INTO n, same, sup
      FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = e->>'version';
    IF NOT FOUND OR n IS DISTINCT FROM (e->>'nodes')::integer OR same IS NOT TRUE THEN
      RAISE EXCEPTION '%:% % must hold this file''s % nodes; found % (tree matches: %)',
        e->>'doc_type', e->>'agency', e->>'version', e->>'nodes',
        coalesce(n::text, 'no row'), coalesce(same::text, 'n/a');
    END IF;
    IF sup IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM c2c_rule_packs
       WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = sup) THEN
      RAISE EXCEPTION '%:% % is superseded by %, which does not exist',
        e->>'doc_type', e->>'agency', e->>'version', sup;
    END IF;
    SELECT count(*) INTO live FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND superseded_by IS NULL;
    IF live <> 1 THEN
      RAISE EXCEPTION '%:% must have exactly one live pack; found %', e->>'doc_type', e->>'agency', live;
    END IF;
  END LOOP;
END
$mig$;
